from lib import *
S = SS('m6')
steps = [
    step("集合里存了两个文档,sub 分别是 {a:1, b:2}(_id 1)和 {b:2, a:1}(_id 2)。查询 {sub: {a: 1, b: 2}} 只返回 _id 1;{sub: {b: 2, a: 1}} 只返回 _id 2——子文档整体匹配要求字段顺序一致。", t=tl(S(1)), mark=lidx(S(1), 'find({sub: {a: 1, b: 2}})', 'find({sub: {b: 2, a: 1}})'), done=lidx(S(1), '_id: 1', '_id: 2'), kv=KV([['整体匹配', '字段顺序也是值的一部分'], ['{a:1,b:2}', '只匹配 _id 1'], ['{b:2,a:1}', '只匹配 _id 2']], ['整体匹配'])),
    step("用点号路径分别匹配 {\"sub.a\": 1, \"sub.b\": 2} 返回 [1, 2],两个文档都命中,与顺序无关;$and 调换条件顺序也一样。但 $expr 里的 $eq 比较整个子文档仍然看顺序,只返回 [1];$group 按 $sub 分组把两种顺序分成两组({a:1,b:2} 与 {b:2,a:1} 各 1 个)。", t=tl(S(2)), mark=lidx(S(2), '$expr', '$group', "_id: { b: 2, a: 1 }"), done=lidx(S(2), '"sub.a": 1', '$and'), kv=KV([['点号路径', '与顺序无关'], ['$expr / $eq 整个子文档', '看顺序'], ['$group 分组键', '顺序不同是不同的组']], ['点号路径'])),
    step("字段位置怎么变:原文档 {_id, a:1, b:2, c:3}。$set 已有字段 b 保持原位:{_id:1, a:1, b:20, c:3};$set 新字段 z 追加到末尾;$unset 了 a 再 $set 回来,a 跑到末尾:{_id:1, b:20, c:3, z:26, a:1};$rename z 为 y,y 出现在末尾:{_id:1, b:20, c:3, a:1, y:26}。", t=tl(S(3)), mark=lidx(S(3), '$unset', '$rename'), done=lidx(S(3), '$set: {b: 20}', '$set: {z: 26}'), kv=KV([['$set 已有字段', '保持原位'], ['$set 新字段', '追加到末尾'], ['$unset 再 $set', '跑到末尾'], ['$rename', '新名字在末尾']], ['$set 已有字段'])),
    step("_id 总是第一个字段:用原始 insert 命令发送 a, _id, b 的顺序,读回来是 { _id: 99, a: 1, b: 2 };replaceOne 用 {b:5, a:4, _id:99} 替换后也是 { _id: 99, b: 5, a: 4 }——服务端把 _id 挪到最前,其它字段保持发送的顺序。", t=tl(S(4)), mark=lidx(S(4), '_id: 99, a: 1, b: 2', '_id: 99, b: 5, a: 4'), done=lidx(S(4), '发送的字段顺序', 'replaceOne'), kv=KV([['_id', '总在最前'], ['其它字段', '保持写入时的顺序']], ['_id'])),
    step("mongosh(JavaScript)构造对象时,像整数的键 \"1\"、\"2\" 会排到最前面:在 mongosh 里插入 {_id:1, b:1, \"2\":2, \"1\":1, a:0},pymongo 读回来的实际字段顺序是 ['_id', '1', '2', 'b', 'a'];用 pymongo 的 SON 按 b, \"2\", \"1\", a 的顺序插入,读回是 ['_id', 'b', '2', '1', 'a']——保序;但 mongosh 显示这个文档时又把整数键排到最前。", t=tl(S(5)), mark=lidx(S(5), "['_id', '1', '2', 'b', 'a']", "['_id', 'b', '2', '1', 'a']"), done=lidx(S(5), 'db.js.insertOne', 'db.py.findOne()'), kv=KV([['JS 对象', '整数键排最前,在客户端就变了'], ['pymongo SON', '保序'], ['mongosh 显示', '也会把整数键提前']], ['JS 对象'])),
    step("字段顺序也影响唯一索引:在 k 上建唯一索引,先后插入 k={a:1,b:2} 和 k={b:2,a:1} 都成功(集合里 2 个文档),再插入一次 k={a:1,b:2} 报 E11000 duplicate key error ... dup key: { k: { a: 1, b: 2 } }。", t=tl(S(6)), mark=lidx(S(6), 'E11000'), done=lidx(S(6), '都成功'), kv=KV([['唯一索引', '顺序不同的子文档是不同的键'], ['建议', '需要唯一性的组合用多个字段,不用子文档']], ['建议'])),
]
A = mkartm('m6', 6, 'MongoDB,字段顺序,子文档,更新,_id,真实验证,动画演示',
    '实测 BSON 字段顺序:子文档整体匹配、$expr 比较、$group 分组键和唯一索引都把字段顺序当成值的一部分,点号路径匹配与顺序无关;$set 保持原位、新字段追加末尾,$unset 再 $set 跑到末尾;_id 总在最前;mongosh 的 JS 对象会把整数键排到最前面。',
    '{a:1,b:2} 和 {b:2,a:1} 是同一个文档吗?这篇用同样内容、不同顺序的子文档,验证整体匹配、点号路径、$expr、分组和唯一索引的行为,再看更新操作怎么移动字段。',
    [('只匹配 1 个', '{sub: {a:1,b:2}} 只匹配字段顺序相同的那一个文档;点号路径匹配则两个都命中'), ('_id 最前', '无论发送时 _id 在第几个位置,存储后总是第一个字段'), ('2 个文档', '唯一索引上 k={a:1,b:2} 与 k={b:2,a:1} 都能插入,因为被当成不同的值')],
    [('整体匹配看顺序', '<p>子文档作为一个值比较时,字段顺序是值的一部分:<code>{sub: {a:1, b:2}}</code> 只匹配字段顺序相同的文档。</p>'),
     ('点号路径与顺序无关', '<p><code>{"sub.a": 1, "sub.b": 2}</code> 分别匹配字段,两个顺序都命中;但 <code>$expr</code> 里 <code>$eq</code> 比较整个子文档、<code>$group</code> 用子文档做分组键,都仍然看顺序。</p>'),
     ('更新怎么移动字段', '<p><code>$set</code> 已有字段保持原位,新字段追加到末尾;<code>$unset</code> 再 <code>$set</code> 或 <code>$rename</code> 会让字段出现在末尾。</p>'),
     ('_id 在最前', '<p>不管插入或替换时 <code>_id</code> 写在哪,服务端都把它放在文档第一位,其它字段保持发送的顺序。</p>'),
     ('客户端会改顺序', '<p>mongosh 里的 JavaScript 对象会把像整数的键排到最前面,所以顺序在客户端构造时就变了;Python 用 <code>SON</code> 或保序的字典则不会。</p>'),
     ('唯一索引', '<p>唯一索引上,字段顺序不同的子文档是不同的键,不会触发重复键错误。需要唯一性的组合,拆成多个字段建复合唯一索引更可靠。</p>')],
    steps,
    [ENV_M + '。字段顺序用 pymongo 的 SON 精确控制,再用 mongosh 与 pymongo 两边读回',
     '没有验证:嵌套多层子文档的 $set 点号路径对顺序的影响;聚合 $addFields / $project 输出的字段顺序;数组里的子文档顺序;复合唯一索引与子文档唯一索引在存储上的差别;其它驱动对字段顺序的处理(Go 的 map 无序等)'],
    '字段顺序')
